<script setup lang="ts">
/**
 * An agent run's steps, each with its status (`design/components/plan.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/plan.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed } from 'vue'

import { Icon } from '@polymorph/vue'
import styles from '@polymorph/recipes/ai/plan.module.css'

export type PlanStatus = 'pending' | 'running' | 'done' | 'error' | 'skipped'

export interface PlanStep {
  id: string
  title: string
  description?: string
  status: PlanStatus
}

export interface PlanMessages {
  status: Record<PlanStatus, string>
}

export interface PlanProps {
  /**
   * The list's accessible name, such as "Plan for this run" rather than "Plan".
   */
  label: string
  /**
   * Omit for the generic English defaults; localized hosts pass their own.
   */
  messages?: PlanMessages
  /**
   * The steps in reading order. Plan never sorts them, and an empty list renders nothing.
   */
  steps: PlanStep[]
}

defineOptions({ name: 'Plan', inheritAttrs: false })

const props = withDefaults(defineProps<PlanProps>(), {
  messages: () => ({
    status: {
      pending: 'Pending',
      running: 'Running',
      done: 'Done',
      error: 'Failed',
      skipped: 'Skipped',
    },
  }),
})
const currentId = computed(() => props.steps.find((step) => step.status === 'running')?.id)
const announcement = computed(() =>
  ((front: PlanStep | undefined) =>
    front === undefined ? '' : `${front.title}, ${props.messages.status[front.status]}`)(
    props.steps.find((step) => step.status === 'running') ??
      props.steps.find((step) => step.status === 'error') ??
      [...props.steps]
        .reverse()
        .find((step) => step.status === 'done' || step.status === 'skipped'),
  ),
)
</script>

<template>
  <div v-if="steps.length > 0" :class="styles.root" data-member="plan">
    <!-- list -->
    <ol :class="styles.list" role="list" :aria-label="label">
      <template v-for="step in steps" :key="step.id">
        <!-- step -->
        <li
          :class="styles.step"
          :data-status="step.status"
          :aria-current="step.id === currentId ? 'step' : undefined"
          :aria-busy="step.status === 'running' ? true : undefined"
        >
          <!-- mark -->
          <span :class="styles.mark" aria-hidden="true">
            <span v-if="step.status === 'running'" :class="[styles.glyph, styles.spinning]">
              <Icon name="loading" size="sm" />
            </span>
            <span v-else-if="step.status === 'done'" :class="styles.glyph">
              <Icon name="success" size="sm" />
            </span>
            <span v-else-if="step.status === 'error'" :class="styles.glyph">
              <Icon name="error" size="sm" />
            </span>
            <span v-else-if="step.status === 'skipped'" :class="styles.glyph">
              <Icon name="remove" size="sm" />
            </span>
            <span v-else :class="styles.glyph">
              <Icon name="time" size="sm" />
            </span>
          </span>
          <!-- copy -->
          <span :class="styles.copy">
            <!-- title -->
            <span :class="styles.title">
              {{ step.title }}
            </span>
            <span :class="styles.reader">
              {{ `, ${messages.status[step.status]}` }}
            </span>
            <!-- description -->
            <span v-if="step.description !== undefined" :class="styles.description">
              {{ step.description }}
            </span>
          </span>
        </li>
      </template>
    </ol>
    <!-- line -->
    <p :class="styles.line" role="status">
      {{ announcement }}
    </p>
  </div>
</template>
